    @Test
    fun invalidSyntax() {
        check("", null)
        check("+", null)
        check("++80", null)
        check("+-0", null)
        check("+ 80", null)
        check(" 80", null)
        check("80 ", null)
        check("80\n", null)
        check("8_0", null)
        check("0x50", null)
        check("1.0", null)
        check("80\u0000", null)
    }

    @Test
    fun overflow() {
        check("65536", null)
        check("99999", null)
        check("2147483647", null)
        check("2147483648", null)
        check("4294967295", null)
        check("18446744073709551615", null)
        check("9999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999", null)
    }

    @Test
    fun allU16Values() {
        for (value in 0..65535) check(value.toString(), value)
    }

    @Test
    fun authorityConsumers() {
        for ((text, expected) in listOf("0" to 0, "80" to 80, "+80" to 80, "00080" to 80, "+00080" to 80, "65535" to 65535, "65536" to null, "-0" to null, "-00" to null, "-1" to null)) {
            val authority = Authority.fromStr("example.org:$text").getOrThrow()
            assertEquals(expected, authority.portU16(), text)
            val port = authority.port()
            if (expected == null) {
                assertTrue(port == null, text)
            } else {
                assertEquals(text, port?.asStr())
                assertEquals(expected.toString(), port?.toString())
            }
        }
    }
}
